17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.nio.charset.StandardCharsets;
20	import java.security.MessageDigest;
21	import java.security.NoSuchAlgorithmException;
22	import java.time.LocalDate;
23	import java.util.ArrayList;
24	import java.util.Collection;
25	import java.util.List;
26	
27	import org.springframework.http.HttpHeaders;
28	import org.springframework.http.HttpStatus;
29	import org.springframework.http.ResponseEntity;
30	import org.springframework.samples.petclinic.mapper.OwnerMapper;
31	import org.springframework.samples.petclinic.mapper.PetMapper;
32	import org.springframework.samples.petclinic.mapper.VisitMapper;
33	import org.springframework.samples.petclinic.model.Owner;
34	import org.springframework.samples.petclinic.model.Pet;
35	import org.springframework.samples.petclinic.model.Visit;
36	import org.springframework.samples.petclinic.rest.advice.DailyOwnerLimitExceededException;
37	import org.springframework.samples.petclinic.rest.advice.DuplicateOwnerException;
38	import org.springframework.samples.petclinic.rest.advice.DuplicateTelephoneException;
39	import org.springframework.samples.petclinic.rest.advice.MissingOwnerFieldsException;
40	import org.springframework.samples.petclinic.rest.advice.OwnerCityFullException;
41	import org.springframework.samples.petclinic.rest.api.OwnersApi;
42	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
43	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
44	import org.springframework.samples.petclinic.rest.dto.PetDto;
45	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
46	import org.springframework.samples.petclinic.rest.dto.VisitDto;
47	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
48	import org.springframework.samples.petclinic.rest.validation.AddressNormalizer;
49	import org.springframework.samples.petclinic.rest.validation.TelephoneNormalizer;
50	import org.springframework.samples.petclinic.service.ClinicService;
51	import org.springframework.security.access.prepost.PreAuthorize;
52	import org.springframework.web.bind.annotation.CrossOrigin;
53	import org.springframework.web.bind.annotation.RequestMapping;
54	import org.springframework.web.bind.annotation.RestController;
55	import org.springframework.web.util.UriComponentsBuilder;
56	
57	import jakarta.transaction.Transactional;
58	
59	/**
60	 * @author Vitaliy Fedoriv
61	 */
62	
63	@RestController
64	@CrossOrigin(exposedHeaders = "errors, content-type")
65	@RequestMapping("/api")
66	public class OwnerRestControllerV1 implements OwnersApi {
67	
68	    /** Maximum number of owners a single city may contain; creating an owner in a full city is rejected. */
69	    private static final int MAX_OWNERS_PER_CITY = 50;
70	
71	    /** Maximum number of owners that may be created in a single day; creating an owner past this cap is rejected. */
72	    private static final int MAX_OWNERS_PER_DAY = 100;
73	
74	    private final ClinicService clinicService;
75	
76	    private final OwnerMapper ownerMapper;
77	
78	    private final PetMapper petMapper;
79	
80	    private final VisitMapper visitMapper;
81	
82	    private final TelephoneNormalizer telephoneNormalizer;
83	
84	    private final AddressNormalizer addressNormalizer;
85	
86	    public OwnerRestControllerV1(ClinicService clinicService,
87	                                 OwnerMapper ownerMapper,
88	                                 PetMapper petMapper,
89	                                 VisitMapper visitMapper,
90	                                 TelephoneNormalizer telephoneNormalizer,
91	                                 AddressNormalizer addressNormalizer) {
92	        this.clinicService = clinicService;
93	        this.ownerMapper = ownerMapper;
94	        this.petMapper = petMapper;
95	        this.visitMapper = visitMapper;
96	        this.telephoneNormalizer = telephoneNormalizer;
97	        this.addressNormalizer = addressNormalizer;
98	    }
99	
100	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
101	    @Override
102	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
103	        Collection<Owner> owners;
104	        if (lastName != null) {
105	            owners = this.clinicService.findOwnerByLastName(lastName);
106	        } else {
107	            owners = this.clinicService.findAllOwners();
108	        }
109	        if (owners.isEmpty()) {
110	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
111	        }
112	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
113	    }
114	
115	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
116	    @Override
117	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
118	        Owner owner = this.clinicService.findOwnerById(ownerId);
119	        if (owner == null) {
120	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
121	        }
122	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
123	    }
124	
125	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
126	    @Override
127	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
128	        normalizeAndValidate(ownerFieldsDto);
129	        HttpHeaders headers = new HttpHeaders();
130	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
131	        owner.setCustomerCode(generateCustomerCode(owner.getCity(), owner.getLastName()));
132	        owner.setNamesakeCount(countNamesakes(owner));
133	        assignHousehold(owner, ownerFieldsDto);
134	        this.clinicService.saveOwner(owner);
135	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
136	        headers.setLocation(UriComponentsBuilder.newInstance()
137	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
138	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
139	    }
140	
141	    /**
142	     * Prepares a new owner's payload for persistence, applying every rule an incoming owner must satisfy before it is
143	     * saved. The address is first normalized to its canonical stored form and written back onto the payload; required
144	     * fields are then checked (so an address that is blank after normalization is rejected); the telephone is
145	     * normalized to its canonical stored form, written back onto the payload and rejected if another owner already uses
146	     * it; the email is canonicalized; and a missing registration date defaults to the current date. The payload is
147	     * mutated in place so the caller can map and save it directly.
148	     *
149	     * @param ownerFieldsDto the incoming owner payload, mutated in place
150	     * @throws MissingOwnerFieldsException if any required field is missing or blank
151	     * @throws DuplicateTelephoneException if another owner already uses the normalized telephone
152	     */
153	    private void normalizeAndValidate(OwnerFieldsDto ownerFieldsDto) {
154	        ownerFieldsDto.setAddress(addressNormalizer.normalize(ownerFieldsDto.getAddress()));
155	        validateRequiredFields(ownerFieldsDto);
156	        String telephone = telephoneNormalizer.normalize(ownerFieldsDto.getTelephone());
157	        ownerFieldsDto.setTelephone(telephone);
158	        requireUniqueTelephone(telephone);
159	        requireUniqueHousehold(ownerFieldsDto);
160	        requireCityHasCapacity(ownerFieldsDto.getCity());
161	        requireDailyLimitNotReached();
162	        ownerFieldsDto.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
163	        if (ownerFieldsDto.getRegistrationDate() == null) {
164	            ownerFieldsDto.setRegistrationDate(LocalDate.now());
165	        }
166	    }
167	
168	    /**
169	     * Rejects creating an owner once the maximum number of owners for the current day has already been reached. The cap
170	     * is 100, so when 100 or more existing owners carry today's {@code registrationDate} no further owner may be created
171	     * today.
172	     *
173	     * @throws DailyOwnerLimitExceededException if 100 or more owners have already been created today
174	     */
175	    private void requireDailyLimitNotReached() {
176	        LocalDate today = LocalDate.now();
177	        long createdToday = this.clinicService.findAllOwners().stream()
178	            .filter(existing -> today.equals(existing.getRegistrationDate()))
179	            .count();
180	        if (createdToday >= MAX_OWNERS_PER_DAY) {
181	            throw new DailyOwnerLimitExceededException(
182	                "the maximum number of owners for today has already been reached");
183	        }
184	    }
185	
186	    /**
187	     * Builds an owner's {@code customerCode}, formatted {@code <CITY3>-<LAST3>-<NNNN>}. {@code CITY3} is the upper-cased
188	     * first three letters of the city, {@code LAST3} the upper-cased first three letters of the last name, and
189	     * {@code NNNN} a per-city 4-digit zero-padded sequence equal to one more than the number of owners already in that
190	     * city (e.g. {@code LON-SMI-0007}).
191	     *
192	     * @param city     the owner's city
193	     * @param lastName the owner's last name
194	     * @return the generated customer code
195	     */
196	    private String generateCustomerCode(String city, String lastName) {
197	        String cityPrefix = city.substring(0, Math.min(3, city.length())).toUpperCase();
198	        String lastPrefix = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
199	        int sequence = (int) this.clinicService.findAllOwners().stream()
200	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
201	            .count() + 1;
202	        return String.format("%s-%s-%04d", cityPrefix, lastPrefix, sequence);
203	    }
204	
205	    /**
206	     * Counts how many existing owners already share the given owner's first and last name, compared
207	     * case-insensitively. Invoked before the new owner is saved, so the result reflects only owners that predate this
208	     * create; it is zero when the owner's name is unique.
209	     *
210	     * @param owner the newly mapped owner about to be saved
211	     * @return the number of existing owners sharing the same first and last name (case-insensitively)
212	     */
213	    private int countNamesakes(Owner owner) {
214	        String firstName = owner.getFirstName();
215	        String lastName = owner.getLastName();
216	        return (int) this.clinicService.findAllOwners().stream()
217	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
218	                && lastName.equalsIgnoreCase(existing.getLastName()))
219	            .count();
220	    }
221	
222	    /**
223	     * Rejects an owner payload that omits or leaves blank any required field. Bean Validation already rejects missing
224	     * ({@code null}) required fields, but permits values that are blank (empty or whitespace-only) for fields without a
225	     * stricter pattern, so this check enforces the "missing or blank" rule uniformly across every required field.
226	     *
227	     * @param ownerFieldsDto the owner payload to validate
228	     * @throws MissingOwnerFieldsException if any of firstName, lastName, address, city or telephone is missing or blank
229	     */
230	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
231	        List<String> missingFields = new ArrayList<>();
232	        requireText(missingFields, "firstName", ownerFieldsDto.getFirstName());
233	        requireText(missingFields, "lastName", ownerFieldsDto.getLastName());
234	        requireText(missingFields, "address", ownerFieldsDto.getAddress());
235	        requireText(missingFields, "city", ownerFieldsDto.getCity());
236	        requireText(missingFields, "telephone", ownerFieldsDto.getTelephone());
237	        if (!missingFields.isEmpty()) {
238	            throw new MissingOwnerFieldsException(missingFields);
239	        }
240	    }
241	
242	    private void requireText(List<String> missingFields, String fieldName, String value) {
243	        if (value == null || value.isBlank()) {
244	            missingFields.add(fieldName);
245	        }
246	    }
247	
248	    /**
249	     * Normalizes an optional owner email. A syntactically valid address is already enforced by Bean Validation on the
250	     * request payload, so this only canonicalizes the value that gets stored and returned by lower-casing it. A missing
251	     * (blank or {@code null}) email is left untouched, since the field is optional.
252	     *
253	     * @param email the raw email value from the request, may be {@code null}
254	     * @return the lower-cased email, or the original value when none was supplied
255	     */
256	    private String normalizeEmail(String email) {
257	        if (email == null || email.isBlank()) {
258	            return email;
259	        }
260	        return email.toLowerCase();
261	    }
262	
263	    /**
264	     * Rejects creating an owner whose normalized telephone is already used by another owner. Existing owners' stored
265	     * telephones are canonicalized the same way before comparison, so the rule holds regardless of how their number was
266	     * originally formatted.
267	     *
268	     * @param telephone the normalized telephone of the owner being created
269	     * @throws DuplicateTelephoneException if any existing owner already uses the same normalized telephone
270	     */
271	    private void requireUniqueTelephone(String telephone) {
272	        boolean inUse = this.clinicService.findAllOwners().stream()
273	            .map(existing -> telephoneNormalizer.canonicalize(existing.getTelephone()))
274	            .anyMatch(telephone::equals);
275	        if (inUse) {
276	            throw new DuplicateTelephoneException("telephone is already in use by another owner");
277	        }
278	    }
279	
280	    /**
281	     * Rejects creating an owner whose city (compared case-insensitively) already contains the maximum number of
282	     * owners. The cap is 50, so a city holding 50 or more owners is full and no further owner may be created there.
283	     *
284	     * @param city the city of the owner being created
285	     * @throws OwnerCityFullException if the city already contains 50 or more owners
286	     */
287	    private void requireCityHasCapacity(String city) {
288	        long cityOwners = this.clinicService.findAllOwners().stream()
289	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
290	            .count();
291	        if (cityOwners >= MAX_OWNERS_PER_CITY) {
292	            throw new OwnerCityFullException("the owner's city already contains the maximum number of owners");
293	        }
294	    }
295	
296	    /**
297	     * Rejects creating an owner who shares a household (see {@link #findHouseholdMembers}) with an existing owner,
298	     * unless the request opts in by setting {@code sharesHousehold} to {@code true}.
299	     *
300	     * @param ownerFieldsDto the incoming owner payload
301	     * @throws DuplicateOwnerException if another owner already belongs to the same household and the request does not
302	     *                                 set {@code sharesHousehold}
303	     */
304	    private void requireUniqueHousehold(OwnerFieldsDto ownerFieldsDto) {
305	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
306	            return;
307	        }
308	        if (!findHouseholdMembers(ownerFieldsDto).isEmpty()) {
309	            throw new DuplicateOwnerException(
310	                "an owner with the same last name and address already exists in this household");
311	        }
312	    }
313	
314	    /**
315	     * Finds the existing owners that belong to the same household as the given payload, i.e. those sharing both its
316	     * last name and address. The last name is compared case-insensitively after collapsing runs of whitespace to a
317	     * single space and trimming; the address is compared in its normalized form (see {@link AddressNormalizer}), so
318	     * incidental formatting differences and abbreviation variants do not affect membership.
319	     *
320	     * @param ownerFieldsDto the incoming owner payload
321	     * @return the existing owners in the same household, in the order {@link ClinicService#findAllOwners()} returns
322	     *         them; empty when none match
323	     */
324	    private List<Owner> findHouseholdMembers(OwnerFieldsDto ownerFieldsDto) {
325	        String lastName = collapseWhitespace(ownerFieldsDto.getLastName());
326	        String address = addressNormalizer.normalize(ownerFieldsDto.getAddress());
327	        return this.clinicService.findAllOwners().stream()
328	            .filter(existing -> collapseWhitespace(existing.getLastName()).equalsIgnoreCase(lastName)
329	                && addressNormalizer.normalize(existing.getAddress()).equals(address))
330	            .toList();
331	    }
332	
333	    /**
334	     * Canonicalizes a value for household comparison by trimming it and collapsing every run of whitespace to a single
335	     * space. Case is deliberately preserved here; callers compare the result case-insensitively.
336	     *
337	     * @param value the raw field value, may be {@code null}
338	     * @return the whitespace-collapsed value, or an empty string when {@code null}
339	     */
340	    private String collapseWhitespace(String value) {
341	        if (value == null) {
342	            return "";
343	        }
344	        return value.strip().replaceAll("\\s+", " ");
345	    }
346	
347	    /**
348	     * Assigns the shared {@code householdId} for an owner joining an existing household. Only owners created with
349	     * {@code sharesHousehold} set to {@code true} that actually match an existing household (see
350	     * {@link #findHouseholdMembers}) are given an identifier; single owners keep a {@code null} household. The
351	     * identifier is derived deterministically from the household's last name and address, so every member of the same
352	     * household resolves to the same stable value regardless of creation order. Existing members that predate the
353	     * feature and still lack the identifier are backfilled so the whole household shares it.
354	     *
355	     * @param owner          the newly mapped owner about to be saved
356	     * @param ownerFieldsDto the incoming owner payload
357	     */
358	    private void assignHousehold(Owner owner, OwnerFieldsDto ownerFieldsDto) {
359	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
360	            return;
361	        }
362	        List<Owner> members = findHouseholdMembers(ownerFieldsDto);
363	        if (members.isEmpty()) {
364	            return;
365	        }
366	        String householdId = generateHouseholdId(ownerFieldsDto);
367	        owner.setHouseholdId(householdId);
368	        for (Owner member : members) {
369	            if (!householdId.equals(member.getHouseholdId())) {
370	                member.setHouseholdId(householdId);
371	                this.clinicService.saveOwner(member);
372	            }
373	        }
374	    }
375	
376	    /**
377	     * Derives a household's stable identifier, formatted {@code HH-<12 hex chars>}, from the case-insensitive,
378	     * whitespace-collapsed last name and the normalized address (see {@link AddressNormalizer}). Being a pure function
379	     * of those fields, it is identical for every owner in the same household and never changes over time.
380	     *
381	     * @param ownerFieldsDto the incoming owner payload
382	     * @return the household identifier
383	     */
384	    private String generateHouseholdId(OwnerFieldsDto ownerFieldsDto) {
385	        String key = collapseWhitespace(ownerFieldsDto.getLastName()).toLowerCase()
386	            + "\n" + addressNormalizer.normalize(ownerFieldsDto.getAddress()).toLowerCase();
387	        try {
388	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(key.getBytes(StandardCharsets.UTF_8));
389	            StringBuilder hex = new StringBuilder();
390	            for (int i = 0; i < 6; i++) {
391	                hex.append(String.format("%02X", digest[i]));
392	            }
393	            return "HH-" + hex;
394	        } catch (NoSuchAlgorithmException ex) {
395	            throw new IllegalStateException("SHA-256 is not available", ex);
396	        }
397	    }
398	
399	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
400	    @Override
401	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
402	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
403	        if (currentOwner == null) {
404	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
405	        }
406	        currentOwner.setAddress(ownerFieldsDto.getAddress());
407	        currentOwner.setCity(ownerFieldsDto.getCity());
408	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
409	        currentOwner.setLastName(ownerFieldsDto.getLastName());
410	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
411	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
412	        this.clinicService.saveOwner(currentOwner);
413	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
414	    }
415	
416	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
417	    @Transactional
418	    @Override
419	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
420	        Owner owner = this.clinicService.findOwnerById(ownerId);
421	        if (owner == null) {
422	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
423	        }
424	        this.clinicService.deleteOwner(owner);
425	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
426	    }
427	
428	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
429	    @Override
430	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
431	        Owner owner = this.clinicService.findOwnerById(ownerId);
432	        if (owner == null) {
433	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
434	        }
435	        HttpHeaders headers = new HttpHeaders();
436	        Pet pet = petMapper.toPet(petFieldsDto);
437	        owner.setId(ownerId);
438	        pet.setOwner(owner);
439	        pet.getType().setName(null);
440	        this.clinicService.savePet(pet);
441	        PetDto petDto = petMapper.toPetDto(pet);
442	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
443	            .buildAndExpand(pet.getId()).toUri());
444	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
445	    }
446	
447	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
448	    @Override
449	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
450	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
451	        if (currentOwner != null) {
452	            Pet currentPet = this.clinicService.findPetById(petId);
453	            if (currentPet != null) {
454	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
455	                currentPet.setName(petFieldsDto.getName());
456	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
457	                this.clinicService.savePet(currentPet);
458	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
459	            }
460	        }
461	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
462	    }
463	
464	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
465	    @Override
466	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
467	        HttpHeaders headers = new HttpHeaders();
468	        Visit visit = visitMapper.toVisit(visitFieldsDto);
469	        Pet pet = new Pet();
470	        pet.setId(petId);
471	        visit.setPet(pet);
472	        this.clinicService.saveVisit(visit);
473	        VisitDto visitDto = visitMapper.toVisitDto(visit);
474	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
475	            .buildAndExpand(visit.getId()).toUri());
476	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
477	    }
478	
479	
480	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
481	    @Override
482	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
483	        Owner owner = this.clinicService.findOwnerById(ownerId);
484	        if (owner != null) {
485	            Pet pet = owner.getPet(petId);
486	            if (pet != null) {
487	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
488	            }
489	        }
490	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
491	    }
492	}
